function g({registerIndicator:c,sma:f,nulls:h}){c({id:"oa-rv",name:"Realized Volatility (RV)",category:"Volatility",placement:"pane",inputs:[{key:"length",type:"number",label:"Smoothing Length",default:20,min:1,max:5e3,step:1,tooltip:"Lookback period for smoothing the period realized volatilities (e.g., daily RVs)."},{key:"annualize",type:"boolean",label:"Annualize Volatility",default:!0,tooltip:"Annualize the Realized Volatility output."},{key:"annualPeriods",type:"number",label:"Annual Periods",default:252,min:1,max:1e5,step:1,tooltip:"Number of main chart periods in a year for annualization (e.g., 252 for Daily chart, 52 for Weekly)."}],plots:[{key:"rv",type:"line",title:"RV",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,l){const m=Math.max(1,Math.floor(Number(l.length)||20)),y=l.annualize!==!1,d=Math.max(1,Math.floor(Number(l.annualPeriods)||252)),t=o.length,i=new Array(t).fill(NaN);for(let e=1;e<t;e++){const a=o[e-1].close,n=o[e].close;if(!Number.isFinite(a)||!Number.isFinite(n)||a<=0||n<=0)continue;const s=Math.log(n/a),b=s*s;i[e]=Math.sqrt(b)}const r=f(i,m),p=y?Math.sqrt(d):1,u=new Array(t).fill(NaN);for(let e=0;e<t;e++)Number.isFinite(r[e])&&(u[e]=r[e]*p);return{rv:h(u)}}})}export{g as default};
